def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 or (r, c) in seen:
                continue

            # Find the connected 6-region.
            stack = [(r, c)]
            seen.add((r, c))
            region = []
            while stack:
                x, y = stack.pop()
                region.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 6 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            # The covered pattern is repeated elsewhere in the grid.
            # Select the translation of this region whose cells are visible.
            best = None
            best_score = -1
            for dr in range(-h + 1, h):
                for dc in range(-w + 1, w):
                    if dr == 0 and dc == 0:
                        continue
                    score = 0
                    for x, y in region:
                        nx, ny = x + dr, y + dc
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 6:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best = (dr, dc)

            if best:
                dr, dc = best
                for x, y in region:
                    nx, ny = x + dr, y + dc
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 6:
                        out[x][y] = grid[nx][ny]

    return out
